import { isValidObjectId } from "mongoose";
import { Customer } from "../../Models/customer.model.js";

export const addCustomer = async (req, res) => {
  try {
    const { name, age, email, address, mobile_no } = req.body;
    if (!name) {
      return res.status(404).json({
        message: "Enter Name",
        success: false
      })
    } else if (!age) {
      return res.status(404).json({
        message: "Enter Age",
        success: false
      })
    } else if (!email) {
      return res.status(404).json({
        message: "Enter Email",
        success: false
      })
    } else if (!address) {
      return res.status(404).json({
        message: "Enter Address",
        success: false
      })
    }
    else if (!mobile_no) {
      return res.status(404).json({
        message: "Enter Mobile Number",
        success: false
      })
    }
    const data = {
      name, age, email, address, mobile_no
    }
    const response = new Customer(data);
    await response.save();
    return res.status(200).json({
      message: "Customer Added Successfully",
      success: true,
      data: response
    })
  } catch (error) {
    console.log(error);
    return res.status(404).json({
      message: "Error While Added Customer",
      success: false,
      error: error.message
    })
  }
}

export const deleteCustomer = async (req, res) => {
  try {
    const { id } = req.params;
    if (!isValidObjectId(id)) {
      return res.status(404).json({
        message: "Invalid Id",
        success: false
      })
    }
    const operation = await Customer.findById(id);
    if (!operation) {
      return res.status(404).json({
        message: "Data not exist in DB",
        success: false
      })
    } else {
      await Customer.findByIdAndDelete(id);
      return res.status(200).json({
        message: "Customer Deleted Successfully",
        success: true,
      })
    }

  } catch (error) {
    console.log(error);
    return res.status(404).json({
      message: "Error while deleting Customer",
      success: false,
      error: error.message
    })
  }
}


export const viewCustomerById = async (req, res) => {
  try {
    const { id } = req.params;
    if (!isValidObjectId(id)) {
      return res.status(404).json({
        message: "Invalid Customer Id",
        success: false
      })
    }
    const operation = await Customer.findById(id);
    if (!operation) {
      return res.status(404).json({
        message: "Data Not Exist In DB",
        success: false
      })
    } else {
      return res.status(200).json({
        message: "Fetched Customer By Id",
        success: true,
        data: operation
      })
    }
  } catch (error) {
    console.log(error);
    return res.status(404).json({
      message: "Error while Viewing data",
      success: false,
      error: error.message
    })
  }
}

