export const editCustomer = async (req, res) => {
  try {
    const { id } = req.params;
    if (!isValidObjectId(id)) {
      return res.status(404).json({
        message: "Invalid Id",
        success: false
      })
    }
    const operation = await Customer.findById(id);
    const data = {
      name: req.body.name,
      age: req.body.age,
      email: req.body.email,
      address: req.body.address,
      mobile_no: req.body.mobile_no
    }
    if (!operation) {
      return res.status(404).json({
        message: "Data not Exist In DB",
        success: false
      })
    } else {
      const updatedata = await Customer.findByIdAndUpdate(id, data, { new: true });
      return res.status(200).json({
        message: "Updated Successfully",
        success: true,
        data: updatedata
      })
    }
  } catch (error) {
    console.log(error);
    return res.status(404).json({
      message: "Error while editing Data",
      success: false,
      error: error.message
    })
  }
}

